{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec('PRAGMA foreign_keys = ON');
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
  default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High')),
  due_date TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))
)`);
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'notes')) {
  db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'deleted')) {
  db.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0');
  db.exec('UPDATE tasks SET position = id');
}
// Keep positions even while a task belongs to another project. Backfill the
// current positions when upgrading an existing database without reordering it.
db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  project_id INTEGER NOT NULL REFERENCES projects(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id),
  UNIQUE (project_id, position)
);
INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks;`);
const listTasks = db.prepare('SELECT id, title, completed, priority, due_date, notes, deleted FROM tasks WHERE project_id = ? ORDER BY position, id');
const findTask = db.prepare('SELECT id, title, completed, priority, due_date, notes, deleted FROM tasks WHERE project_id = ? AND id = ?');
const createTask = db.prepare('INSERT INTO tasks (project_id, title, priority, position) VALUES (?, ?, ?, ?)');
const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id = ?');
const rememberedPosition = db.prepare('SELECT position FROM task_positions WHERE task_id = ? AND project_id = ?');
const savePosition = db.prepare('INSERT INTO task_positions (task_id, project_id, position) VALUES (?, ?, ?)');
const moveTask = db.prepare('UPDATE tasks SET project_id = ?, position = ? WHERE project_id = ? AND id = ?');

function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const setTaskPriority = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setTaskDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const setTaskNotes = db.prepare('UPDATE tasks SET notes = ? WHERE project_id = ? AND id = ?');
const setTaskDeleted = db.prepare('UPDATE tasks SET deleted = ? WHERE project_id = ? AND id = ?');
const taskData = task => ({ ...task, completed: Boolean(task.completed), deleted: Boolean(task.deleted) });
const projectQuery = `SELECT projects.id, projects.name, projects.archived, projects.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id AND deleted = 0) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id AND deleted = 0 AND completed = 1) AS completed
  FROM projects`;
const listProjects = db.prepare(`${projectQuery} ORDER BY projects.id`);
const findProject = db.prepare(`${projectQuery} WHERE projects.id = ?`);
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const assets = new Map([
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);
const page = readFileSync(new URL('./public/index.html', import.meta.url));

function validDueDate(value) {
  if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

function sendJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

async function readJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') return sendJson(res, 200, { status: 'ok' });
    if (req.method === 'GET' && path === '/api/projects') return sendJson(res, 200, listProjects.all());
    const taskMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskMatch) {
      const [, projectId, taskId] = taskMatch;
      const project = findProject.get(projectId);
      if (!project) return sendJson(res, 404, { error: 'Project not found' });
      if (req.method === 'GET' && !taskId) return sendJson(res, 200, listTasks.all(projectId).map(taskData));
      if (project.archived && (req.method === 'POST' || req.method === 'PATCH')) {
        return sendJson(res, 409, { error: 'Archived project' });
      }
      if (req.method === 'POST' && !taskId) {
        const input = await readJson(req);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return sendJson(res, 400, { error: 'Task title is required' });
        const result = transaction(() => {
          const { position } = nextPosition.get(projectId);
          const created = createTask.run(projectId, title, project.default_priority, position);
          savePosition.run(created.lastInsertRowid, projectId, position);
          return created;
        });
        return sendJson(res, 201, taskData(findTask.get(projectId, result.lastInsertRowid)));
      }
      if (req.method === 'PATCH' && taskId) {
        const task = findTask.get(projectId, taskId);
        if (!task) return sendJson(res, 404, { error: 'Task not found' });
        const input = await readJson(req);
        if (input && Object.hasOwn(input, 'deleted')) {
          if (typeof input.deleted !== 'boolean') return sendJson(res, 400, { error: 'Deletion state must be a boolean' });
          setTaskDeleted.run(Number(input.deleted), projectId, taskId);
          return sendJson(res, 200, taskData(findTask.get(projectId, taskId)));
        }
        if (task.deleted) return sendJson(res, 409, { error: 'Deleted task must be restored before editing' });
        if (input && Object.hasOwn(input, 'destination_project_id')) {
          const destinationId = input.destination_project_id;
          if (!Number.isSafeInteger(destinationId) || destinationId <= 0 || destinationId === Number(projectId)) {
            return sendJson(res, 400, { error: 'Choose another active project' });
          }
          const destination = findProject.get(destinationId);
          if (!destination) return sendJson(res, 404, { error: 'Destination project not found' });
          if (destination.archived) return sendJson(res, 409, { error: 'Archived project' });
          transaction(() => {
            let saved = rememberedPosition.get(taskId, destinationId);
            if (!saved) {
              saved = nextPosition.get(destinationId);
              savePosition.run(taskId, destinationId, saved.position);
            }
            moveTask.run(destinationId, saved.position, projectId, taskId);
          });
          return sendJson(res, 200, taskData(findTask.get(destinationId, taskId)));
        } else if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return sendJson(res, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return sendJson(res, 400, { error: 'Task priority must be Low, Normal, or High' });
          }
          setTaskPriority.run(input.priority, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'due_date')) {
          const dueDate = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (dueDate === null || (dueDate !== '' && !validDueDate(dueDate))) {
            return sendJson(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setTaskDueDate.run(dueDate, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'notes')) {
          if (typeof input.notes !== 'string') return sendJson(res, 400, { error: 'Task notes must be text' });
          setTaskNotes.run(input.notes, projectId, taskId);
        } else {
          if (typeof input?.completed !== 'boolean') return sendJson(res, 400, { error: 'Completion must be a boolean' });
          updateTask.run(Number(input.completed), projectId, taskId);
        }
        return sendJson(res, 200, taskData(findTask.get(projectId, taskId)));
      }
    }
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && match) {
      const project = findProject.get(match[1]);
      return sendJson(res, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (req.method === 'PATCH' && match) {
      const project = findProject.get(match[1]);
      if (!project) return sendJson(res, 404, { error: 'Project not found' });
      const input = await readJson(req);
      if (input && Object.hasOwn(input, 'name')) {
        if (project.archived) return sendJson(res, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return sendJson(res, 400, { error: 'Project name is required' });
        renameProject.run(name, match[1]);
      } else if (input && Object.hasOwn(input, 'default_priority')) {
        if (project.archived) return sendJson(res, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return sendJson(res, 400, { error: 'Default task priority must be Low, Normal, or High' });
        }
        setDefaultPriority.run(input.default_priority, match[1]);
      } else {
        if (typeof input?.archived !== 'boolean') return sendJson(res, 400, { error: 'Archive state must be a boolean' });
        updateProject.run(Number(input.archived), match[1]);
      }
      return sendJson(res, 200, findProject.get(match[1]));
    }
    if (req.method === 'POST' && path === '/api/projects') {
      const input = await readJson(req);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return sendJson(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return sendJson(res, 201, findProject.get(result.lastInsertRowid));
    }
    if (req.method === 'GET' && assets.has(path)) {
      const [type, body] = assets.get(path);
      res.writeHead(200, { 'Content-Type': type });
      return res.end(body);
    }
    if (req.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path))) {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return res.end(page);
    }
    sendJson(res, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return sendJson(res, error.status, { error: error.message });
    console.error(error);
    sendJson(res, 500, { error: 'Unable to complete request' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  return node;
}

function showAlert(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p', '', { role: 'alert' });
    app.append(alert);
  }
  alert.textContent = message;
  alert.hidden = !message;
}

function normalizeSearch(value) {
  return value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, letter => letter.toLowerCase());
}

function searchForm(kind, onSearch) {
  const form = element('form', '', { class: 'search-form' });
  const input = element('input', '', { id: `${kind}-search`, type: 'text', autocomplete: 'off' });
  const controls = element('div', '', { class: 'controls' });
  controls.append(input, element('button', `Search ${kind}s`, { type: 'submit' }));
  form.append(element('label', `${kind === 'project' ? 'Project' : 'Task'} search`, { for: input.id }), controls);
  form.addEventListener('submit', event => {
    event.preventDefault();
    input.value = input.value.trim();
    onSearch(normalizeSearch(input.value));
  });
  return form;
}

function validDueDate(value) {
  if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

function projectRow(project, onUpdate) {
  const row = element('div', '', { 'data-testid': 'project-row', class: 'project-row' });
  const open = element('button', 'Open project', { type: 'button' });
  open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project', { type: 'button' });
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const updated = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, updated);
      showAlert('');
      onUpdate();
    } catch (error) { showAlert(error.message); archive.disabled = false; }
  });
  row.append(element('span', project.name),
    element('span', `${project.completed}/${project.total} completed`, { 'data-testid': 'project-summary' }),
    open, archive);
  return row;
}

async function renderTasks(project) {
  const endpoint = `/api/projects/${project.id}/tasks`;
  const form = element('form');
  const input = element('input', '', { id: 'task-title', type: 'text', autocomplete: 'off' });
  const submit = element('button', 'Create task', { type: 'submit' });
  submit.disabled = true;
  const controls = element('div', '', { class: 'controls' });
  controls.append(input, submit);
  form.append(element('label', 'Task title', { for: 'task-title' }), controls);
  const filter = element('select', '', { id: 'task-filter' });
  for (const value of ['All', 'Open', 'Completed', 'Deleted']) filter.append(element('option', value, { value }));
  const priorityFilter = element('select', '', { id: 'priority-filter' });
  for (const value of ['All', 'Low', 'Normal', 'High']) priorityFilter.append(element('option', value, { value }));
  const filters = element('div', '', { class: 'filters' });
  filters.append(element('label', 'Task filter', { for: 'task-filter' }), filter,
    element('label', 'Priority filter', { for: 'priority-filter' }), priorityFilter);
  const rangeForm = element('form', '', { class: 'due-range-form' });
  const dueFrom = element('input', '', { id: 'due-from', type: 'text', autocomplete: 'off' });
  const dueThrough = element('input', '', { id: 'due-through', type: 'text', autocomplete: 'off' });
  rangeForm.append(element('label', 'Due from', { for: dueFrom.id }), dueFrom,
    element('label', 'Due through', { for: dueThrough.id }), dueThrough,
    element('button', 'Apply due range', { type: 'submit' }));
  const list = element('section', '', { 'aria-label': 'Tasks', class: 'tasks' });
  const search = searchForm('task', query => {
    appliedQuery = query;
    drawTasks();
  });
  app.append(form, element('p', '', { role: 'alert', hidden: '' }), filters, rangeForm, search, list);
  let tasks = [];
  let destinations = [];
  let appliedFrom = '';
  let appliedThrough = '';
  let appliedQuery = '';
  function drawTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (Boolean(task.deleted) !== (filter.value === 'Deleted')) continue;
      const readOnly = Boolean(project.archived || task.deleted);
      if (!normalizeSearch(task.title).includes(appliedQuery)) continue;
      if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
      if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
      if (appliedFrom || appliedThrough) {
        if (!task.due_date || (appliedFrom && task.due_date < appliedFrom) ||
          (appliedThrough && task.due_date > appliedThrough)) continue;
      }
      const row = element('div', '', { 'data-testid': 'task-row', class: 'task-row' });
      const checkbox = element('input', '', { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
      checkbox.checked = task.completed;
      checkbox.disabled = readOnly;
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        try {
          const updated = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          Object.assign(task, updated);
          showAlert('');
        } catch (error) { showAlert(error.message); }
        finally { drawTasks(); }
      });
      row.append(checkbox, element('span', task.title));
      const priorityControls = element('div');
      const priority = element('select', '', { id: `task-priority-${task.id}` });
      for (const value of ['Low', 'Normal', 'High']) {
        priority.append(element('option', value, { value }));
      }
      priority.value = task.priority;
      priority.disabled = readOnly;
      priority.addEventListener('change', async () => {
        priority.disabled = true;
        try {
          Object.assign(task, await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: priority.value }),
          }));
          showAlert('');
        } catch (error) { showAlert(error.message); }
        finally { drawTasks(); }
      });
      priorityControls.append(element('label', 'Task priority', { for: priority.id }), priority);
      row.append(priorityControls);
      const renameForm = element('form', '', { class: 'task-rename-form' });
      const renameInput = element('input', '', { id: `new-task-title-${task.id}`, type: 'text', autocomplete: 'off' });
      const renameButton = element('button', 'Rename task', { type: 'submit' });
      renameInput.disabled = readOnly;
      renameButton.disabled = readOnly;
      const renameControls = element('div', '', { class: 'controls' });
      renameControls.append(renameInput, renameButton);
      renameForm.append(element('label', 'New task title', { for: renameInput.id }), renameControls);
      renameForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (readOnly) return;
        const title = renameInput.value.trim();
        if (!title) return showAlert('Task title is required');
        renameButton.disabled = true;
        try {
          Object.assign(task, await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
          }));
          showAlert('');
          drawTasks();
          document.getElementById(`new-task-title-${task.id}`)?.focus();
        } catch (error) { showAlert(error.message); }
        finally { renameButton.disabled = readOnly; }
      });
      row.append(renameForm);
      const dueForm = element('form', '', { class: 'task-due-form' });
      const dueInput = element('input', '', { id: `task-due-date-${task.id}`, type: 'text', autocomplete: 'off' });
      dueInput.value = task.due_date;
      const dueButton = element('button', 'Save due date', { type: 'submit' });
      dueInput.disabled = readOnly;
      dueButton.disabled = readOnly;
      const dueControls = element('div', '', { class: 'controls' });
      dueControls.append(dueInput, dueButton);
      dueForm.append(element('label', 'Task due date', { for: dueInput.id }), dueControls);
      dueForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (readOnly) return;
        dueButton.disabled = true;
        try {
          Object.assign(task, await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ due_date: dueInput.value.trim() }),
          }));
          dueInput.value = task.due_date;
          showAlert('');
          drawTasks();
        } catch (error) { showAlert(error.message); }
        finally { dueButton.disabled = readOnly; }
      });
      row.append(dueForm);
      const notesForm = element('form', '', { class: 'task-notes-form' });
      const notesInput = element('textarea', '', { id: `task-notes-${task.id}`, rows: '4' });
      notesInput.value = task.notes;
      const notesButton = element('button', 'Save notes', { type: 'submit' });
      notesInput.disabled = readOnly;
      notesButton.disabled = readOnly;
      notesForm.append(element('label', 'Task notes', { for: notesInput.id }), notesInput, notesButton);
      notesForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (readOnly) return;
        notesButton.disabled = true;
        try {
          Object.assign(task, await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ notes: notesInput.value }),
          }));
          showAlert('');
          drawTasks();
        } catch (error) { showAlert(error.message); }
        finally { notesButton.disabled = readOnly; }
      });
      row.append(notesForm);
      const moveForm = element('form', '', { class: 'task-move-form' });
      const destination = element('select', '', { id: `destination-project-${task.id}` });
      for (const target of destinations) {
        destination.append(element('option', target.name, { value: String(target.id) }));
      }
      const moveButton = element('button', 'Move task', { type: 'submit' });
      const cannotMove = readOnly || destinations.length === 0;
      destination.disabled = cannotMove;
      moveButton.disabled = cannotMove;
      moveForm.append(element('label', 'Destination project', { for: destination.id }), destination, moveButton);
      moveForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (cannotMove) return;
        moveButton.disabled = true;
        destination.disabled = true;
        try {
          await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ destination_project_id: Number(destination.value) }),
          });
          tasks = tasks.filter(candidate => candidate.id !== task.id);
          showAlert('');
          drawTasks();
        } catch (error) {
          showAlert(error.message);
          moveButton.disabled = cannotMove;
          destination.disabled = cannotMove;
        }
      });
      row.append(moveForm);
      const deletion = element('button', task.deleted ? 'Restore task' : 'Delete task', { type: 'button' });
      deletion.disabled = Boolean(project.archived);
      deletion.addEventListener('click', async () => {
        if (project.archived) return;
        deletion.disabled = true;
        try {
          Object.assign(task, await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ deleted: !task.deleted }),
          }));
          showAlert('');
          drawTasks();
        } catch (error) { showAlert(error.message); deletion.disabled = Boolean(project.archived); }
      });
      row.append(deletion);
      list.append(row);
    }
  }
  filter.addEventListener('change', drawTasks);
  priorityFilter.addEventListener('change', drawTasks);
  rangeForm.addEventListener('submit', event => {
    event.preventDefault();
    const from = dueFrom.value.trim();
    const through = dueThrough.value.trim();
    if ((from && !validDueDate(from)) || (through && !validDueDate(through))) {
      return showAlert('Due range must use valid YYYY-MM-DD dates');
    }
    if (from && through && from > through) {
      return showAlert('Due from must not be after Due through');
    }
    appliedFrom = from;
    appliedThrough = through;
    dueFrom.value = from;
    dueThrough.value = through;
    showAlert('');
    drawTasks();
  });
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    const title = input.value.trim();
    if (!title) return showAlert('Task title is required');
    submit.disabled = true;
    try {
      tasks.push(await request(endpoint, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
      }));
      drawTasks();
      input.value = '';
      showAlert('');
      input.focus();
    } catch (error) { showAlert(error.message); }
    finally { submit.disabled = Boolean(project.archived); }
  });
  const [savedTasks, projects] = await Promise.all([request(endpoint), request('/api/projects')]);
  tasks = savedTasks;
  destinations = projects.filter(target => !target.archived && target.id !== project.id);
  drawTasks();
  submit.disabled = Boolean(project.archived);
}

function renderDefaultPriority(project) {
  const controls = element('div', '', { class: 'rename-form' });
  const select = element('select', '', { id: 'default-task-priority' });
  for (const value of ['Low', 'Normal', 'High']) select.append(element('option', value, { value }));
  select.value = project.default_priority;
  select.disabled = Boolean(project.archived);
  select.addEventListener('change', async () => {
    select.disabled = true;
    try {
      Object.assign(project, await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ default_priority: select.value }),
      }));
      showAlert('');
    } catch (error) { showAlert(error.message); }
    finally {
      select.value = project.default_priority;
      select.disabled = Boolean(project.archived);
    }
  });
  controls.append(element('label', 'Default task priority', { for: select.id }), select);
  app.append(controls);
}

function renderRename(project, heading) {
  const form = element('form', '', { class: 'rename-form' });
  const input = element('input', '', { id: 'new-project-name', type: 'text', autocomplete: 'off' });
  const submit = element('button', 'Rename project', { type: 'submit' });
  input.disabled = Boolean(project.archived);
  submit.disabled = Boolean(project.archived);
  const controls = element('div', '', { class: 'controls' });
  controls.append(input, submit);
  form.append(element('label', 'New project name', { for: 'new-project-name' }), controls);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    const name = input.value.trim();
    if (!name) return showAlert('Project name is required');
    submit.disabled = true;
    try {
      Object.assign(project, await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
      }));
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = '';
      showAlert('');
      input.focus();
    } catch (error) { showAlert(error.message); }
    finally { submit.disabled = Boolean(project.archived); }
  });
  app.append(form);
}

async function render() {
  app.replaceChildren();
  const match = window.location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    const back = element('button', 'Projects', { type: 'button', class: 'back' });
    back.addEventListener('click', () => { window.location.href = '/'; });
    app.append(back);
    const project = await request(`/api/projects/${match[1]}`);
    document.title = `${project.name} · Workboard`;
    const heading = element('h1', project.name);
    app.append(heading);
    if (project.archived) app.append(element('p', 'Archived project'));
    renderRename(project, heading);
    renderDefaultPriority(project);
    await renderTasks(project);
    return;
  }
  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', '', { id: 'project-name', name: 'name', type: 'text', autocomplete: 'off' });
  const submit = element('button', 'Create project', { type: 'submit' });
  submit.disabled = true;
  const controls = element('div', '', { class: 'controls' });
  controls.append(input, submit);
  form.append(label, controls);
  const list = element('section', '', { 'aria-label': 'Projects', class: 'projects' });
  const alert = element('p', '', { role: 'alert', hidden: '' });
  const filter = element('select', '', { id: 'project-filter' });
  for (const value of ['Active', 'Archived']) filter.append(element('option', value, { value }));
  const filters = element('div', '', { class: 'filters' });
  filters.append(element('label', 'Project filter', { for: 'project-filter' }), filter);
  const search = searchForm('project', query => {
    appliedQuery = query;
    drawProjects();
  });
  app.append(form, alert, filters, search, list);
  let projects = [];
  let appliedQuery = '';
  function drawProjects() {
    list.replaceChildren();
    for (const project of projects) {
      if (Boolean(project.archived) === (filter.value === 'Archived') &&
        normalizeSearch(project.name).includes(appliedQuery)) {
        list.append(projectRow(project, drawProjects));
      }
    }
  }
  filter.addEventListener('change', drawProjects);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) return showAlert('Project name is required');
    submit.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
      });
      projects.push(project);
      drawProjects();
      input.value = '';
      showAlert('');
      input.focus();
    } catch (error) { showAlert(error.message); }
    finally { submit.disabled = false; }
  });
  projects = await request('/api/projects');
  drawProjects();
  submit.disabled = false;
}

render().catch(error => showAlert(error.message)).finally(() => app.setAttribute('aria-busy', 'false'));
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { DatabaseSync } from 'node:sqlite';

test('Task 015 upgrade, deletion, restoration, reserved order, ownership, summaries, and restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-deletion-'));
  const database = join(directory, 'workboard.sqlite');
  const notes = '  Preserved\n雪 😀 <b>literal</b>\n\t ';
  const legacy = new DatabaseSync(database);
  legacy.exec(`CREATE TABLE projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0, default_priority TEXT NOT NULL DEFAULT 'Normal'
  );
  CREATE TABLE tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0,
    priority TEXT NOT NULL DEFAULT 'Normal', due_date TEXT NOT NULL DEFAULT '',
    notes TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE task_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id), project_id INTEGER NOT NULL REFERENCES projects(id),
    position INTEGER NOT NULL, PRIMARY KEY (task_id, project_id), UNIQUE (project_id, position)
  );
  INSERT INTO projects (name) VALUES ('Source'), ('Destination');
  INSERT INTO tasks (project_id, title, completed, priority, due_date, position) VALUES
    (1, 'First', 1, 'High', '0001-01-01', 10), (1, 'Second', 0, 'Low', '', 20);
  INSERT INTO task_positions VALUES (1, 1, 10), (2, 1, 20), (1, 2, 5);`);
  legacy.prepare('UPDATE tasks SET notes = ? WHERE id = 1').run(notes);
  legacy.close();
  let child;
  let base;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: '0', DB_PATH: database }, stdio: ['ignore', 'pipe', 'pipe'],
    });
    base = await new Promise((resolve, reject) => {
      let output = '';
      const timer = setTimeout(() => reject(new Error('Server startup timeout')), 10000);
      child.once('error', reject);
      child.once('exit', code => { clearTimeout(timer); reject(new Error(`Server exited: ${code}`)); });
      child.stdout.on('data', chunk => {
        output += chunk;
        const match = output.match(/listening on port (\d+)/);
        if (match) { clearTimeout(timer); resolve(`http://127.0.0.1:${match[1]}`); }
      });
    });
  }
  async function stop() {
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
    child = undefined;
  }
  const call = async (path, method = 'GET', body) => {
    const response = await fetch(`${base}${path}`, {
      method, ...(body === undefined ? {} : { headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }),
    });
    return { status: response.status, data: await response.json() };
  };
  const tasks = async id => (await call(`/api/projects/${id}/tasks`)).data;
  const edit = (project, task, body) => call(`/api/projects/${project}/tasks/${task}`, 'PATCH', body);
  const summary = async id => {
    const { data } = await call(`/api/projects/${id}`);
    return [data.completed, data.total];
  };
  try {
    await start();
    assert.deepEqual(await call('/health'), { status: 200, data: { status: 'ok' } });
    const original = await tasks(1);
    assert.deepEqual(original, [
      { id: 1, title: 'First', completed: true, priority: 'High', due_date: '0001-01-01', notes, deleted: false },
      { id: 2, title: 'Second', completed: false, priority: 'Low', due_date: '', notes: '', deleted: false },
    ]);
    for (const deleted of ['true', 1, null]) assert.equal((await edit(1, 1, { deleted })).status, 400);
    assert.equal((await edit(2, 1, { deleted: true })).status, 404);
    assert.equal((await edit(1, 999, { deleted: true })).status, 404);
    assert.deepEqual((await edit(1, 1, { deleted: true })).data, { ...original[0], deleted: true });
    assert.deepEqual(await summary(1), [0, 1]);
    for (const body of [
      { completed: false }, { title: 'Changed' }, { priority: 'Normal' },
      { due_date: '' }, { notes: '' }, { destination_project_id: 2 },
    ]) assert.equal((await edit(1, 1, body)).status, 409);
    await edit(1, 2, { deleted: true });
    assert.deepEqual(await summary(1), [0, 0]);
    await call('/api/projects/1', 'PATCH', { default_priority: 'Normal', });
    const third = (await call('/api/projects/1/tasks', 'POST', { title: 'Third' })).data;
    assert.equal(third.deleted, false);
    assert.equal(third.notes, '');
    await call('/api/projects/1', 'PATCH', { archived: true });
    assert.equal((await edit(1, 1, { deleted: false })).status, 409);
    assert.equal((await edit(1, third.id, { deleted: true })).status, 409);
    await stop();
    await start();
    assert.deepEqual(await tasks(1), [{ ...original[0], deleted: true }, { ...original[1], deleted: true }, third]);
    assert.deepEqual(await summary(1), [0, 1]);
    await call('/api/projects/1', 'PATCH', { archived: false });
    // Restore in reverse order; neither restoration nor default changes replace fields.
    assert.deepEqual((await edit(1, 2, { deleted: false })).data, original[1]);
    assert.deepEqual((await edit(1, 1, { deleted: false })).data, original[0]);
    assert.deepEqual(await tasks(1), [...original, third]);
    assert.deepEqual(await summary(1), [1, 3]);
    await edit(1, 1, { destination_project_id: 2 });
    assert.deepEqual(await tasks(2), [original[0]]);
    assert.deepEqual(await summary(2), [1, 1]);
    await edit(2, 1, { deleted: true });
    assert.deepEqual(await summary(2), [0, 0]);
    assert.equal((await edit(2, 1, { destination_project_id: 1 })).status, 409);
    await stop();
    await start();
    await edit(2, 1, { deleted: false });
    await edit(2, 1, { destination_project_id: 1 });
    assert.deepEqual(await tasks(1), [...original, third]);
    assert.deepEqual(await tasks(2), []);
    await stop();
    await start();
    assert.deepEqual(await tasks(1), [...original, third]);
    assert.deepEqual(await summary(1), [1, 3]);
  } finally {
    if (child) await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
# Workboard

Requires Node.js 22.22.1. No application dependencies are needed.

```sh
npm start
```

The server listens on `0.0.0.0:8080` by default. Set `PORT` and `DB_PATH` to configure the port and persistent SQLite file:

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
```

Visit `/` to create and open projects. `GET /health` returns `{"status":"ok"}`.

Within a project, create tasks, check or uncheck completion, and use Task filter
to show All, Open, Completed, or Deleted tasks. Projects, tasks, and completion persist in
the configured SQLite file across restarts.

Use Project filter to view Active or Archived projects. Archive and restore
projects from their rows; summaries count completed and total live tasks.
Archived project pages allow viewing and filtering tasks, with creation and
completion controls disabled. Existing databases are upgraded automatically.

On an active project page, use New project name and Rename project to change
its name while preserving its URL, creation order, tasks, and summary. Archived
projects must be restored before renaming.

Each task row provides New task title and Rename task. Renaming preserves task
order, project ownership, completion, and summary counts, and updates the
completion checkbox label. Archived projects must be restored before task
renaming is enabled.

Each task has a Task priority selector with Low, Normal, and High options.
Existing tasks retain their priorities; new tasks inherit their project's
default. Priorities persist independently of task titles and completion; archived projects disable priority changes until
restored.

Use Priority filter to show All, Low, Normal, or High priorities together with
Task filter. Tasks must match both filters and keep their creation order.
Completion and priority edits immediately refresh the matching rows while
preserving both filter selections. Both filters work in archived projects;
filtering leaves saved tasks and completion summaries unchanged.

Each project has a Default task priority selector with Low, Normal, and High
options, initially Normal. Changes apply only to subsequently created tasks in
that project and preserve both task filters. Defaults persist across restarts,
renaming, archival, and restoration; archived projects disable the selector.

Each task has an optional Task due date textbox and Save due date button. Dates
must be real Gregorian calendar dates in YYYY-MM-DD format, with years 0001
through 9999. Surrounding whitespace is trimmed, and an empty value clears the
date. Invalid values show an alert and leave the saved date unchanged. Dates
persist across restarts and renaming without changing task filters or other
task data. Archived projects disable both due-date controls until restored.

Run the integration and UI checks with `npm test`.

Use Due from and Due through, then Apply due range, to intersect an inclusive
calendar-date range with Task filter and Priority filter. Blank boundaries are
unbounded; any nonblank boundary excludes undated tasks. Both blank includes
all dates and undated tasks. Invalid dates or reversed boundaries show an alert
and preserve the previously applied range. Task edits immediately refresh the
matching rows while retaining all filters. Range controls also work in archived
projects. Reopening a project starts with empty range boundaries.

Use Destination project and Move task in a task row to move it to another
active project. Destinations use current project names in project creation
order. On its first arrival, the task appends after all positions established
in the destination. Returning to a previous project restores its remembered
position relative to that project's other tasks, even when several tasks
return in a different order. Positions persist separately per project across
restarts, project renaming, archival, and restoration, preserving current task
identity, title, completion, priority, and due date. The source page stays open
with all filters retained, and both project summaries reflect the move.
Archived projects cannot send or receive tasks. Move controls are disabled
when the source is archived or no eligible destination exists.

Use Project search and Search projects to match project names, together with
Project filter. Use Task search and Search tasks to match task titles, together
with completion, priority, and the applied due range. Searches trim surrounding
query whitespace, treat each run of ASCII spaces and horizontal tabs as one
space for matching, and ignore ASCII letter case. Stored names and titles keep
their original internal whitespace and case.
Blank queries match everything allowed by the other filters. Editing or moving
tasks retains the applied query and filters and immediately refreshes matching
rows. Search also works in archived projects without enabling task edits.
Opening either page starts with an empty search query; returning through
Projects resets project search. Searches leave saved data and summary counts
unchanged.

Every task row provides Task notes and Save notes. Notes are optional multiline
plain text: saving preserves spaces, line breaks, Unicode, and literal markup;
saving empty text clears them. Notes persist through restarts, renames, moves,
and return-order restoration. They do not participate in search or affect
filters or completion summaries. Archived projects show notes with editing
disabled; restoration enables editing again. Existing databases initialize
only the new notes field to empty while retaining prior task data.

Use Delete task to keep a task in the Deleted filter while removing it from live
filters and completion summaries. Deleted tasks retain all fields and remembered
positions across restarts, with editing and movement disabled. Restore task
returns the task to its reserved position without changing saved fields. The
Deleted filter intersects priority, due range, and title search; deletion and
restoration preserve those controls. Archived projects allow reading deleted
tasks but disable deletion and restoration until the project is restored.
Existing databases upgrade all earlier tasks as live.

